import{c as e,Z as o,Q as i,j as r,m as l,o as s}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"静夜思","description":"","frontmatter":{"title":"静夜思","author":"李白","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/1.md","filePath":"books/shici/tangshi/1.md"}'),n={name:"books/shici/tangshi/1.md"};function h(d,a,c,p,u,m){const t=o("PoemNav");return i(),r("div",null,[a[0]||(a[0]=l('<h1 id="静夜思" tabindex="-1">静夜思 <a class="header-anchor" href="#静夜思" aria-label="Permalink to &quot;静夜思&quot;">​</a></h1><p><strong>[唐] <a href="/authors/libai.html">李白</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>床前明月光，疑是地上霜。 举头望明月，低头思故乡。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>疑：好像</li><li>举头：抬头</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>明亮的月光洒在床前的窗户纸上，好像地上泛起了一层霜。我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗写的是在寂静的月夜思念家乡的感受。诗的前两句，是写诗人在作客他乡的特定环境中一刹那间所产生的错觉。一个独处他乡的人，白天奔波忙碌，倒还能冲淡离愁，然而一到夜深人静的时候，心头就难免泛起阵阵思念故乡的波澜。何况是在月明之夜，更何况是月色如霜的秋夜。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>李白</strong>（701年－762年），字太白，号青莲居士，又号“谪仙人”，唐代伟大的浪漫主义诗人，被后人誉为“诗仙”。其诗风雄奇豪放，想象丰富，意境奇妙，语言流转自然。</p><p><a href="/authors/libai.html">查看作者详情 →</a></p></blockquote>',13)),s(t,{currentId:1,category:"tangshi",poems:[{id:1,title:"静夜思"},{id:2,title:"春晓"},{id:3,title:"登鹳雀楼"},{id:4,title:"相思"},{id:5,title:"江雪"},{id:6,title:"悯农"}]})])}const f=e(n,[["render",h]]);export{b as __pageData,f as default};
